  IF to_regclass('"fm"."file_versions"') IS NULL THEN missing := missing || E'\n  line 76: table fm.file_versions not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."file_versions"')
                    AND attname = 'file_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 76: column file_id not found in fm.file_versions [AZ601]';
  END IF;
  IF to_regclass('"fm"."file_versions"') IS NULL THEN missing := missing || E'\n  line 76: table fm.file_versions not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."file_versions"')
                    AND attname = 'object_key' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 76: column object_key not found in fm.file_versions [AZ601]';
  END IF;
  IF to_regclass('"fm"."file_versions"') IS NULL THEN missing := missing || E'\n  line 76: table fm.file_versions not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."file_versions"')
                    AND attname = 'created_by' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 76: column created_by not found in fm.file_versions [AZ601]';
  END IF;
  IF to_regclass('"fm"."groups"') IS NULL THEN missing := missing || E'\n  line 84: table fm.groups not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."groups"')
                    AND attname = 'parent_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 84: column parent_id not found in fm.groups [AZ601]';
  END IF;
  IF to_regclass('"fm"."groups"') IS NULL THEN missing := missing || E'\n  line 85: table fm.groups not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."groups"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 85: column id not found in fm.groups [AZ601]';
  END IF;
  IF to_regclass('"fm"."groups"') IS NULL THEN missing := missing || E'\n  line 85: table fm.groups not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."groups"')
                    AND attname = 'owner_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 85: column owner_id not found in fm.groups [AZ601]';
  END IF;
  IF to_regclass('"fm"."group_members"') IS NULL THEN missing := missing || E'\n  line 92: table fm.group_members not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"fm"."group_members"')
                    AND attname = 'group_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 92: column group_id not found in fm.group_members [AZ601]';
  END IF;
  IF to_regclass('"fm"."users"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."users"') AND attname = 'id') <> to_regtype('uuid') THEN
    missing := missing || E'\n  line 7: fm.users.id is not uuid; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"fm"."groups"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."groups"') AND attname = 'id') <> to_regtype('uuid') THEN
    missing := missing || E'\n  line 9: fm.groups.id is not uuid; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"fm"."group_members"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."group_members"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 19: fm.group_members.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"fm"."folders"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."folders"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 25: fm.folders.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"fm"."files"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."files"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 37: fm.files.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"fm"."file_versions"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"fm"."file_versions"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 48: fm.file_versions.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

-- Who is asking: SELECT authz.act_as('user', '42') first in each transaction (a signed session).
DO $u$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE oid = to_regprocedure('authz.uid()')
             AND prorettype <> 'uuid'::regtype) THEN
    RAISE EXCEPTION 'authz.uid() returns another type than this policy''s user ids (uuid); drop it first (DROP FUNCTION authz.uid() CASCADE drops what uses it) [AZ606]';
  END IF;
END $u$;

CREATE OR REPLACE FUNCTION authz.uid() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $uid$ BEGIN RETURN CASE WHEN authz_int.session_ok() AND coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'uuid') THEN pg_catalog.current_setting('authz.user_id', true)::uuid END; END $uid$;

CREATE SCHEMA authz_gen;
CREATE SCHEMA authz_int;

-- Signed sessions: the key, made once and kept in authz.settings (the app role can't read either)
CREATE TABLE authz_int.session_key (ipad bytea NOT NULL, opad bytea NOT NULL);
INSERT INTO authz.settings (key, value)
  VALUES ('session_key', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  ON CONFLICT (key) DO NOTHING;
DO $sk$
DECLARE k bytea; i bytea; o bytea;
BEGIN
  SELECT decode(value, 'hex') INTO k FROM authz.settings WHERE key = 'session_key';
  k := k || decode(repeat('00', 64 - length(k)), 'hex');
  i := k; o := k;
  FOR n IN 0..63 LOOP
    i := set_byte(i, n, get_byte(k, n) # 54);
    o := set_byte(o, n, get_byte(k, n) # 92);
  END LOOP;
  INSERT INTO authz_int.session_key VALUES (i, o);
END $sk$;
-- HMAC-SHA256 of who is signed in, this backend and this transaction
CREATE FUNCTION authz_int.session_sig() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex');
END $f$;
-- signs the settings as they are now: for rowfence's own functions, after they switch who is signed in
CREATE FUNCTION authz_int.sign() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM set_config('authz.session', authz_int.session_sig(), true);
END $f$;
-- Are the settings to be believed? PL/pgSQL, so its plans are kept for the session, and not a definer: all its
-- callers run as the owner. (OR runs left to right: the refusal is asked only when the signature doesn't match.)
CREATE FUNCTION authz_int.session_ok() RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN coalesce(current_setting('authz.session', true) = pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex'), false) OR authz_int.session_refused();
END $f$;
-- When the signature doesn't match: true for the owner's and superusers' sessions, else an error saying why
CREATE FUNCTION authz_int.session_refused() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_sig text := coalesce(current_setting('authz.session', true), '');
BEGIN
  -- the policy's owner and superusers say who is signed in by setting it (psql, migrations, tests)
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN true;
  END IF;
  IF v_sig <> '' THEN
    RAISE EXCEPTION 'who is signed in was changed after signing in' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'say who is signed in with authz.act_as(), never by setting authz.user_id or the other authz settings '
             '(rowfence help AZ702)';
  ELSIF coalesce(current_setting('authz.user_id', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.user_id was set directly, so it is not believed' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'sign in with SELECT authz.act_as(''user'', ''42''), authz.login_key() or authz.login_jwt() (rowfence help AZ702)';
  END IF;
  RAISE EXCEPTION 'nobody signed in in this transaction' USING ERRCODE = 'invalid_authorization_specification',
    HINT = 'start each transaction with SELECT authz.act_as(''user'', ''42''), or authz.act_as(NULL, NULL) for nobody '
           '(or authz.login_key() / authz.login_jwt()) (rowfence help AZ701)';
END $f$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7' (invalid ids as they are)
CREATE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN p_id::uuid::text; END IF;
    WHEN 'group' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN p_id::uuid::text; END IF;
    WHEN 'membership' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'folder' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'file' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'version' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;

-- Who is signed in, whatever their type: SELECT * FROM authz.principal()
CREATE FUNCTION authz.principal() RETURNS TABLE (principal_type text, principal_id text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  principal_type := coalesce(nullif(pg_catalog.current_setting('authz.principal_type', true), ''), 'user');
  CASE principal_type
    WHEN 'user' THEN principal_id := authz.uid()::text;
    ELSE RETURN;
  END CASE;
  IF principal_id IS NOT NULL THEN RETURN NEXT; END IF;
END $f$;
-- how the audit trail and created_by name who acted: a user's id, or type:id for other principals
CREATE FUNCTION authz_int.actor() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN CASE WHEN NOT authz_int.session_ok() THEN NULL
              WHEN coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') THEN nullif(current_setting('authz.user_id', true), '')
              ELSE pg_catalog.current_setting('authz.principal_type', true) || ':' || nullif(current_setting('authz.user_id', true), '') END;
END $f$;

-- per type: its table, key, how to find a row x by an id ($1, text), and a row's id (columns unqualified)
CREATE TABLE authz_int.types (name text PRIMARY KEY, tbl text NOT NULL, pk text NOT NULL, pktype text NOT NULL,
  keytype text NOT NULL, find text NOT NULL, id_of text NOT NULL, principal boolean NOT NULL);

