-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND (c.relname LIKE 'shares\_obj\_%' OR c.relname LIKE 'grants\_obj\_%')
             AND c.relname <> ALL (ARRAY['shares_obj_user_uuid', 'shares_obj_group_uuid', 'shares_obj_membership_bigint', 'shares_obj_folder_bigint', 'shares_obj_file_bigint', 'shares_obj_version_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_uuid" ON authz.shares ((object_id::uuid), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_group_uuid" ON authz.shares ((object_id::uuid), relation) WHERE object_type = 'group';
CREATE INDEX IF NOT EXISTS "shares_obj_membership_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'membership';
CREATE INDEX IF NOT EXISTS "shares_obj_folder_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'folder';
CREATE INDEX IF NOT EXISTS "shares_obj_file_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'file';
CREATE INDEX IF NOT EXISTS "shares_obj_version_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'version';

-- Scopes: what a token may do (policy 'scope' lines; 'read' is built in unless redefined)
CREATE TABLE authz_int.scope_items (scope text, kind text, qual text, word text);
INSERT INTO authz_int.scope_items VALUES
  ('read', 'cmd', NULL, 'select'),
  ('read', 'perm', NULL, '*');

-- the scopes this transaction is limited to (NULL: not limited); believed only if signed, like the user
CREATE FUNCTION authz_int.scopes_active() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE WHEN NOT authz_int.session_ok() THEN ARRAY[]::text[]
              WHEN coalesce(current_setting('authz.scopes', true), '') = '' THEN NULL
              ELSE ARRAY(SELECT btrim(x) FROM unnest(string_to_array(current_setting('authz.scopes', true), ',')) x
                         WHERE btrim(x) <> '') END $f$;
-- may this transaction run a command on a table?
CREATE FUNCTION authz_int.scope_cmd(p_table text, p_cmd text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                              AND i.word = p_cmd AND (i.qual IS NULL OR i.qual = p_table))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction ask about (or use) a permission?
CREATE FUNCTION authz_int.scope_perm(p_type text, p_perm text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'perm'
                              AND (i.word = p_perm OR i.word = '*') AND (i.qual IS NULL OR i.qual = p_type))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction change anything? (not while viewing as someone, not with read-only scopes)
CREATE FUNCTION authz_int.writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(current_setting('authz.acting_user', true), '') = ''
     AND (s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                               AND i.word <> 'select'))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
CREATE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ704';
  END IF;
END $f$;
-- the role that called (inside SECURITY DEFINER functions current_user is the owner)
CREATE FUNCTION authz_int.caller_role() RETURNS text
LANGUAGE sql STABLE AS $f$
  SELECT CASE WHEN current_setting('role') = 'none' THEN session_user::text ELSE current_setting('role') END $f$;
-- The caller is an administrator, not the app: a superuser, BYPASSRLS, or the policy's owner (or a member of it)
CREATE FUNCTION authz_int.caller_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce((SELECT r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid, n.nspowner, 'MEMBER')
                   FROM pg_roles r, pg_namespace n
                   WHERE r.rolname = authz_int.caller_role() AND n.nspname = 'authz_int'), false) $f$;
-- one row in the audit trail
CREATE FUNCTION authz_int.audit(p_action text, p_object_type text, p_object_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text, p_detail jsonb) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation,
                           subject_type, subject_id, subject_relation, detail, reason)
  VALUES (authz_int.caller_role(), authz_int.actor(),
          nullif(current_setting('authz.acting_user', true), ''), p_action, p_object_type, p_object_id, p_relation,
          p_subject_type, p_subject_id, p_subject_relation, p_detail,
          nullif(current_setting('authz_ctx.reason', true), '')) $f$;

-- The change feed: objects whose access may have changed. Consumers poll authz.changes_since(pos).
-- NOTIFY on channel authz_changes only with INSERT INTO authz.settings VALUES ('notify_changes', 'on'):
-- Postgres commits notifying transactions one at a time, so it would queue every write.
CREATE FUNCTION authz_int.changed(p_type text, p_ids text[], p_cause text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_pos bigint;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  INSERT INTO authz.changes (object_type, object_ids, cause) VALUES (p_type, p_ids, p_cause) RETURNING pos INTO v_pos;
  IF (SELECT s.value FROM authz.settings s WHERE s.key = 'notify_changes') = 'on' THEN
    PERFORM pg_notify('authz_changes', v_pos::text);
  END IF;
END $f$;
-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowfence help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days.
CREATE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_to bigint; n bigint;
BEGIN
  SELECT max(c.pos) INTO v_to FROM authz.changes c WHERE c.at < now() - v_keep;
  IF v_to IS NULL THEN RETURN 0; END IF;
  DELETE FROM authz.changes c WHERE c.pos <= v_to;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text)
    ON CONFLICT (key) DO UPDATE SET value = greatest(authz.settings.value::bigint, v_to)::text;
  RETURN n;
END $f$;
-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING HINT = 'rowfence help AZ710';
  END IF;
  v_before := now() - p_keep;
  PERFORM set_config('authz_int.trim_before', v_before::text, true);
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('authz_int.trim_before', '', true);
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit()
CREATE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.at < nullif(current_setting('authz_int.trim_before', true), '')::timestamptz THEN RETURN OLD; END IF;
  END IF;
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ711';
END $f$;
CREATE TRIGGER authz_audit_append_only BEFORE UPDATE OR DELETE ON authz.audit
  FOR EACH ROW EXECUTE FUNCTION authz_int.audit_is_append_only();
CREATE TRIGGER authz_audit_no_truncate BEFORE TRUNCATE ON authz.audit
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int.audit_is_append_only();

-- shares and role assignments
CREATE FUNCTION authz_int.on_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  IF TG_OP = 'UPDATE' AND OLD.object_id <> NEW.object_id THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_grant_audit AFTER INSERT OR UPDATE OR DELETE ON authz.shares
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_grant();
CREATE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    PERFORM authz_int.audit(CASE TG_OP WHEN 'DELETE' THEN 'role_permission_removed' ELSE 'role_permission_added' END,
      NULL, NULL, 'role:' || CASE WHEN TG_OP = 'DELETE' THEN OLD.role_id ELSE NEW.role_id END, NULL, NULL, NULL,
      jsonb_build_object('permission', CASE WHEN TG_OP = 'DELETE' THEN OLD.permission ELSE NEW.permission END));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_audit AFTER INSERT OR UPDATE OR DELETE ON authz.roles
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();
CREATE TRIGGER authz_role_perm_audit AFTER INSERT OR DELETE ON authz.role_permissions
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "fm"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND NOT EXISTS (SELECT 1 FROM "fm"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'group' AND NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'group' AND NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'membership' AND NOT EXISTS (SELECT 1 FROM "fm"."group_members" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'membership' AND NOT EXISTS (SELECT 1 FROM "fm"."group_members" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'folder' AND NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'folder' AND NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'file' AND NOT EXISTS (SELECT 1 FROM "fm"."files" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'file' AND NOT EXISTS (SELECT 1 FROM "fm"."files" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'version' AND NOT EXISTS (SELECT 1 FROM "fm"."file_versions" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'version' AND NOT EXISTS (SELECT 1 FROM "fm"."file_versions" x WHERE x."id"::text = g.subject_id);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions)
CREATE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- relations ('role:<id>') of the custom roles that include a permission
CREATE FUNCTION authz_int.role_relations(p_type text, p_perm text) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(array_agg('role:' || r.id), '{}') FROM authz.roles r
  JOIN authz.role_permissions p ON p.role_id = r.id
  WHERE r.object_type = p_type AND p.permission = p_perm $f$;
-- deleting a role removes its assignments
CREATE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_gone AFTER DELETE ON authz.roles
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.role_gone();

-- group: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."group__parent__tree" (descendant uuid NOT NULL, ancestor uuid NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."group__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('group', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."group__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."group__parent__tree";
    ALTER TABLE authz_keep."group__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('group__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."group__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."group__parent__tree_compute"(p_ids uuid[]) RETURNS TABLE (o_descendant uuid, o_ancestor uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."groups" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."groups" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "fm"."groups" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."group__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 9: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."group__parent__tree_shift"(p_ids uuid[], p_below uuid[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched uuid[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."group__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."group__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."groups" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."group__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."group__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."group__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."group__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."group__parent__tree_refresh"(p_ids uuid[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected uuid[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."group__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."group__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('group', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE)
CREATE FUNCTION authz_int."group__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  DELETE FROM authz_int."group__parent__tree";
  INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
  SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(ARRAY(SELECT "id" FROM "fm"."groups"));
END $f$;
CREATE FUNCTION authz_int."group__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."group__parent__tree_rebuild"(); RETURN NULL; END $f$;

CREATE FUNCTION authz_int."group__parent__tree_verify"() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH fresh AS (SELECT o_descendant AS d, o_ancestor AS a
                 FROM authz_int."group__parent__tree_compute"(ARRAY(SELECT "id" FROM "fm"."groups")))
  SELECT NOT EXISTS ((SELECT d, a FROM fresh EXCEPT SELECT descendant, ancestor FROM authz_int."group__parent__tree")
                     UNION ALL
                     (SELECT descendant, ancestor FROM authz_int."group__parent__tree" EXCEPT SELECT d, a FROM fresh))
$f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."group__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."group__parent__tree_check_loops"(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."group__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'group % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowfence help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."group__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids uuid[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."group__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."group__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_group__parent__tree_ins" AFTER INSERT ON "fm"."groups"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_upd" AFTER UPDATE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_del" AFTER DELETE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_trunc" AFTER TRUNCATE ON "fm"."groups"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'group__parent__tree') THEN
    PERFORM authz_int."group__parent__tree_rebuild"();
  END IF;
END $b$;

-- folder: each row with every ancestor it inherits from, through parent while {inherit}
CREATE TABLE authz_int."folder__parent__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."folder__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('folder', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder__parent__tree";
    ALTER TABLE authz_keep."folder__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."folder__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder__parent__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."folders" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."folders" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))
      AND EXISTS (SELECT 1 FROM "fm"."folders" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- the conditions on each row (and the type's where)
CREATE VIEW authz_int."folder__parent__tree_conds" AS
  SELECT r."id" AS id, ARRAY[coalesce((inherit), false)] AS v FROM "fm"."folders" r;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN
  CREATE TEMP TABLE authz_probe (LIKE "fm"."folders");
  BEGIN
    CREATE INDEX ON authz_probe ((coalesce((inherit), false)));
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'line 31: a condition that limits inheritance must give the same answer for every user at any time (%) [AZ603]', SQLERRM;
  END;
  DROP TABLE authz_probe;
  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."folder__parent__tree_links"'::regclass, 'authz_int."folder__parent__tree_conds"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 31: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE ((e._link = 0 AND coalesce((inherit), false))) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE ((e._link = 0 AND coalesce((inherit), false))));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."folders" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE)
CREATE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
  SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(ARRAY(SELECT "id" FROM "fm"."folders"));
END $f$;
CREATE FUNCTION authz_int."folder__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder__parent__tree_rebuild"(); RETURN NULL; END $f$;

CREATE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH fresh AS (SELECT o_descendant AS d, o_ancestor AS a
                 FROM authz_int."folder__parent__tree_compute"(ARRAY(SELECT "id" FROM "fm"."folders")))
  SELECT NOT EXISTS ((SELECT d, a FROM fresh EXCEPT SELECT descendant, ancestor FROM authz_int."folder__parent__tree")
                     UNION ALL
                     (SELECT descendant, ancestor FROM authz_int."folder__parent__tree" EXCEPT SELECT d, a FROM fresh))
$f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."folder__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."folder__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'folder % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowfence help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
         OR (SELECT coalesce((inherit), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((inherit), false) FROM (SELECT o.*) r)
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."folder__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_ins" AFTER INSERT ON "fm"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_upd" AFTER UPDATE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_del" AFTER DELETE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_trunc" AFTER TRUNCATE ON "fm"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();
  END IF;
END $b$;

-- trees kept but no longer used (none, normally) go with the holding schema
DROP SCHEMA authz_keep CASCADE;

-- shares on user rows that are gone, or whose id changed, are removed
CREATE FUNCTION authz_int."user__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    DELETE FROM authz.shares WHERE object_type = 'user';
    DELETE FROM authz.shares WHERE subject_type = 'user';
  ELSE
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
  END IF;
  RETURN NULL;
END $f$;
CREATE FUNCTION authz_int."user__forget_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  DELETE FROM authz.shares WHERE object_type = 'user' AND object_id = OLD."id"::text;
  DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id = OLD."id"::text;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_user_forget_del" AFTER DELETE ON "fm"."users"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__forget"();
CREATE TRIGGER "authz_user_forget_id" AFTER UPDATE ON "fm"."users" FOR EACH ROW
  WHEN (OLD."id" IS DISTINCT FROM NEW."id") EXECUTE FUNCTION authz_int."user__forget_id"();
CREATE TRIGGER "authz_user_forget_trunc" AFTER TRUNCATE ON "fm"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__forget"();

