-- relationships kept in fm.group_members
CREATE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((is_admin), false)) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((is_admin), false)) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
-- @object trigger "authz_rel_audit_1_ins" ON "fm"."group_members"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"fm"."group_members"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_ins" AFTER INSERT ON "fm"."group_members" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_ins"()';
  ELSE
    RAISE NOTICE '"fm"."group_members" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."rel_audit_1_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((is_admin), false)) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((is_admin), false)) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((is_admin), false)) c GROUP BY c.ot;
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((is_admin), false)) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((is_admin), false)) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'group' AS ot, x."group_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((is_admin), false)) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
-- @object trigger "authz_rel_audit_1_upd" ON "fm"."group_members"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"fm"."group_members"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_upd" AFTER UPDATE ON "fm"."group_members" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_upd"()';
  ELSE
    RAISE NOTICE '"fm"."group_members" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."rel_audit_1_del"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
