  WITH RECURSIVE m(id) AS (
    SELECT id FROM (
  SELECT s."group_id" AS id FROM "fm"."group_members" s WHERE s."user_id" = (SELECT authz.uid())) d
    UNION
    SELECT unnest(ARRAY(SELECT e.obj FROM (
  SELECT s."parent_id" AS obj, s."id" AS subj FROM "fm"."groups" s WHERE s."id" IS NOT NULL AND s."parent_id" IS NOT NULL) e WHERE e.subj = m.id)) FROM m)
  SELECT id FROM m;
