CREATE FUNCTION authz_gen."fm.folders:insert:items"(p_row "fm"."folders") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce((owner_id = (SELECT authz.uid())), false)
    AND (coalesce((parent_id is null), false)
    OR authz_gen."folder__edit__has"("folders"."parent_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('fm.folders', 'insert')), false),
    coalesce(true, false),
    coalesce((coalesce((parent_id is null), false)
    OR authz_gen."folder__edit__has"("folders"."parent_id")), false),
    coalesce(coalesce((parent_id is null), false), false),
    coalesce(authz_gen."folder__edit__has"("folders"."parent_id"), false),
    coalesce(coalesce((owner_id = (SELECT authz.uid())), false), false)]
  FROM (SELECT (p_row).*) AS "folders";
END;

CREATE FUNCTION authz_gen."fm.folders:insert:why"(p_row "fm"."folders") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."fm.folders:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : ({parent_id is null} or parent.edit) and {owner_id = authz.uid()}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule fm.folders insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on fm.folders'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || '({parent_id is null} or parent.edit)';
  IF NOT v[4] THEN
    RETURN NEXT CASE WHEN v[5] THEN '    yes  ' ELSE '    no   ' END || '{parent_id is null}';
    RETURN NEXT CASE WHEN v[6] THEN '    yes  ' ELSE '    no   ' END || 'parent.edit';
  IF NOT v[6] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("folders"."parent_id")::text AS id FROM (SELECT (p_row).*) AS "folders") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('folder', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  END IF;
  RETURN NEXT CASE WHEN v[7] THEN '  yes  ' ELSE '  no   ' END || '{owner_id = authz.uid()}';
END $f$;

